SELECT b.CSNAME AS `股票名称`, a.COMB_SYMBOL AS `股票代码`, ROUND(c.F021N, 2) AS `市盈率`, c.F022D AS `市盈率更新时间` FROM AMERICAN_STOCK_MAIN a INNER JOIN COM3101 c ON a.FIU_ID = c.FIU_ID INNER JOIN AMERICAN_STOCK_MAIN b ON c.FIU_ID = b.FIU_ID WHERE (a.COMB_SYMBOL = 'TSLA.US' OR b.CSNAME LIKE '%特斯拉%' OR b.CSNAME LIKE '%Tesla%') AND c.F021N IS NOT NULL ORDER BY c.F021N DESC LIMIT 1;
